export const samples = [
 {id:'architecture',name:'system-design.md',text:`# Evidence Lab: system design\nEvidence Lab is a browser document question answering tool. The pipeline ingests plain text and Markdown documents, creates overlapping word chunks, ranks those chunks with BM25, and assembles verbatim excerpts with source citations. It uses no generative language model and no semantic embeddings.\n\n# Chunking strategy\nDocuments are chunked into configurable windows of 60, 120, or 240 words. Consecutive chunks overlap by 20 percent to preserve context at boundaries. Each chunk stores the document identifier, document name, chunk number, and original text. Smaller chunks can improve precision; larger chunks preserve more surrounding context.\n\n# Retrieval\nBM25 is a lexical ranking algorithm that scores passages using query term frequency, inverse document frequency, and document length normalization. Common English stop words are excluded. The parameters are k1 equals 1.5 and b equals 0.75. The top two, three, or five positive-scoring chunks are returned. Lexical retrieval cannot reliably match synonyms that share no words.\n\n# Evidence assembly\nThe highest scoring sentence from each retrieved chunk is shown verbatim with a citation. The complete source chunk can be expanded below the answer. These excerpts are evidence, not a generated explanation. A BM25 score is a relevance ranking signal, not a calibrated probability or confidence score.`},
 {id:'trust',name:'trust-and-privacy.md',text:`# Privacy guarantees\nUploaded documents are processed entirely in browser memory. Document contents and questions are not sent to an API or external server. Reloading the page clears uploaded files and restores the sample corpus. The website may load fonts from Google Fonts, but document processing does not make external requests.\n\n# Unsupported questions\nWhen a question has no matching query terms in the corpus, the system returns a no-evidence response instead of inventing an answer. Partial lexical matches can still produce irrelevant passages. Users must inspect source citations to judge support. This system does not validate factual correctness or guarantee semantic relevance.\n\n# File support\nThe upload interface supports text-based PDFs and UTF-8 plain text and Markdown. PDF text is extracted locally using PDF.js with page-number citations. Each file may be up to 2 MB. A session supports up to 20 documents and 8 MB of combined text. PDFs can have up to 100 pages. Scanned or image-only PDFs need OCR, which is not supported. Password-protected PDFs, Word documents, and images are not supported. Uploaded text is rendered using safe text nodes rather than interpreted as HTML.\n\n# Prompt injection\nDocuments are treated as untrusted data. Because the tool has no language model, tool execution, or external actions, instructions embedded in documents are displayed as text and are not executed. This design does not demonstrate prompt injection defenses for an LLM-backed application.`},
 {id:'evaluation',name:'evaluation-notes.md',text:`# Evaluation methodology\nThe included evaluation uses five fixed checks against the bundled sample corpus. Three questions check whether an expected source document appears among the top three retrieved passages. One check verifies refusal on a query containing only absent terms. One check verifies that a known sentence is preserved exactly by extractive assembly.\n\n# Evaluation limits\nThis small deterministic smoke suite validates retrieval wiring, no-match behavior, and source fidelity. It is not a benchmark of generative answer faithfulness, production readiness, or performance on arbitrary uploads. The suite uses a fresh sample index, independent of the current uploaded documents and settings.\n\n# Extending to generative RAG\nA generative RAG deployment could add an embedding model, hybrid retrieval, a reranker, and a language model that answers from retrieved context. Evaluate retrieval recall separately from answer quality. Keep citations, measure unsupported answer rates, test prompt injection, and monitor latency and model cost. This browser demo implements lexical retrieval and extractive evidence assembly only.\n\n# Trace export\nA downloadable JSON trace includes the question, retrieval settings, elapsed retrieval time, retrieved passages, raw BM25 scores, and assembled excerpts. Export is initiated by the visitor and includes source text; visitors choose whether to share that trace.`}
];
const stop=new Set('a an the is are was were be been being to of in on at and or for with this that it its how what why when where does do can my your as by from about i me has have into which'.split(' '));
export function tokenize(text){return (text.toLowerCase().match(/[\p{L}\p{N}]+/gu)||[]).filter(w=>w.length>1&&!stop.has(w));}
export function buildIndex(documents,size=120){
  const chunks=[];
  for(const doc of documents){
    let number=0;
    for(const section of doc.pages||[{text:doc.text}]){
      const words=section.text.match(/\S+/g)||[],step=Math.max(1,Math.floor(size*.8));
      for(let start=0;start<words.length;start+=step){
        const text=words.slice(start,start+size).join(' '),terms=tokenize(text),freq=new Map();
        for(const term of terms)freq.set(term,(freq.get(term)||0)+1);
        number++;chunks.push({id:`${doc.id}:${number}`,docId:doc.id,name:doc.name,number,page:section.page??null,text,terms,freq});
        if(start+size>=words.length)break;
      }
    }
  }
  const df=new Map();for(const c of chunks)for(const t of c.freq.keys())df.set(t,(df.get(t)||0)+1);
  return {chunks,df,avg:chunks.reduce((n,c)=>n+c.terms.length,0)/(chunks.length||1)};
}
export function search(index,question,k=3){const terms=[...new Set(tokenize(question))];const N=index.chunks.length;return index.chunks.map(c=>{let score=0;for(const t of terms){const f=c.freq.get(t)||0;if(!f)continue;const df=index.df.get(t)||0;score+=Math.log(1+(N-df+.5)/(df+.5))*f*2.5/(f+1.5*(.25+.75*c.terms.length/(index.avg||1)));}return {...c,score};}).filter(c=>c.score>0).sort((a,b)=>b.score-a.score).slice(0,k);}
export function excerpt(chunk,question){const terms=new Set(tokenize(question));const sentences=chunk.text.split(/(?<=[.!?])\s+/u);return sentences.map((s,i)=>({s:s.trim(),i,n:tokenize(s).reduce((n,t)=>n+(terms.has(t)?1:0),0)})).filter(x=>x.s).sort((a,b)=>b.n-a.n||a.i-b.i)[0]?.s||chunk.text;}
export function evaluate(){const index=buildIndex(samples);const checks=[['Chunking source','How are documents chunked?','architecture'],['Privacy source','What are the privacy guarantees?','trust'],['Evaluation source','What evaluation methodology is used?','evaluation']].map(([name,q,id])=>({name,pass:search(index,q).some(c=>c.docId===id)}));checks.push({name:'No-match response',pass:search(index,'xylophonic zeppelins quasars').length===0});const chunk={text:'Alpha is a test sentence. Documents stay in browser memory.'};checks.push({name:'Verbatim excerpt fidelity',pass:excerpt(chunk,'Where do documents stay?')==='Documents stay in browser memory.'});return checks;}
